var n=`0906-kung-pao-chicken`;var t=`world-0906`;var a=`CN`;var s=`east-asia`;var o=4;var r=54;var g={en:`Kung Pao Chicken`,ua:`Курка гунбао`};var h={en:`Kung Pao Chicken is a China dish made with chicken breast, light soy sauce, cornstarch, dried arbol chilies. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Курка гунбао, страва кухні країни Китай. Основні складники: куряча грудка, світлий соєвий соус, кукурудзяний крохмаль, сушений перець арболь. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`chicken-breast`,680,`g`],[`light-soy-sauce`,32,`ml`],[`shaoxing-wine`,25,`ml`],[`cornstarch`,20,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`peanut-oil`,50,`ml`],[`dried-arbol-chilies`,8,`pcs`],[`sichuan-peppercorn`,4,`g`],[`garlic`,4,`clove`],[`ground-ginger`,20,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`green-bell-pepper`,180,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`black-rice-vinegar`,45,`ml`],[`white-granulated-sugar`,28,`g`],[`light-soy-sauce`,28,`ml`],[`peanut`,100,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`green-onion`,45,`g`]]}];var u={slug:n,id:t,country:`CN`,region:s,servings:4,minutes:54,title:g,text:h,steps:l};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,n as slug,l as steps,h as text,g as title};